import ast

def flatten_dict(d, parent_key='', sep='.'):  # same helper as original
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

def main():
    s = input()
    d = ast.literal_eval(s)
    flat = flatten_dict(d)
    print(flat)

if __name__ == "__main__":
    main()

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def main():
    nums = list(map(int, input().strip().split()))
    primes = [num for num in nums if is_prime(num)]
    if not primes:
        print()
        return
    n = len(nums)
    dp = [1] * n
    prev = [-1] * n
    for i in range(n):
        if not is_prime(nums[i]):
            continue
        for j in range(i):
            if is_prime(nums[j]) and nums[j] < nums[i] and dp[i] < dp[j] + 1:
                dp[i] = dp[j] + 1
                prev[i] = j
    maxlen = 0
    maxidx = -1
    for i in range(n):
        if is_prime(nums[i]) and dp[i] > maxlen:
            maxlen = dp[i]
            maxidx = i
    if maxidx == -1:
        print()
        return
    seq = []
    while maxidx != -1:
        seq.append(nums[maxidx])
        maxidx = prev[maxidx]
    print(' '.join(map(str, reversed(seq))))

if __name__ == "__main__":
    main()

import ast

def flatten_array(arr):
    stack = arr[::-1]
    flat_list = []
    while stack:
        next_item = stack.pop()
        if isinstance(next_item, (list, tuple)):
            stack.extend(next_item[::-1])
        elif isinstance(next_item, set):
            # Sets are unordered, but we flatten all items in the set
            # Convert to list for consistency (order arbitrary)
            stack.extend(list(next_item)[::-1])
        elif isinstance(next_item, dict):
            # Only flatten dictionary values
            stack.extend(list(next_item.values())[::-1])
        else:
            flat_list.append(next_item)
    return flat_list

def main():
    s = input()
    arr = ast.literal_eval(s)
    res = flatten_array(arr)
    print(res)

if __name__ == "__main__":
    main()

class Employee:
    _all_salaries = []

    def __init__(self, name, emp_id, salary):
        self.__name = name
        self.__emp_id = emp_id
        self.__salary = salary
        Employee._all_salaries.append(salary)

    def apply_raise(self, percentage=5):
        raise_amount = self.__salary * (percentage / 100)
        self.__salary += raise_amount

    def get_employee_details(self):
        return f"Employee Name: {self.__name}, Employee ID: {self.__emp_id}, Salary: ${self.__salary:.2f}"

    @staticmethod
    def average_salary():
        if not Employee._all_salaries:
            return 0
        # For updating, get the current instances' average
        return sum([emp._Employee__salary for emp in Employee._instances]) / len(Employee._instances)

Employee._instances = []

def main():
    N = int(input())
    employees = []
    for _ in range(N):
        line = input().strip()
        name, emp_id, salary = line.split()
        emp = Employee(name, int(emp_id), float(salary))
        employees.append(emp)
        Employee._instances.append(emp)
    M = int(input())
    for _ in range(M):
        parts = input().strip().split()
        idx = int(parts[0])
        if len(parts) > 1:
            perc = float(parts[1])
            employees[idx].apply_raise(perc)
        else:
            employees[idx].apply_raise()
    for emp in employees:
        print(emp.get_employee_details())
    print(f"Average Salary: ${Employee.average_salary():.2f}")

if __name__ == "__main__":
    main()

