import sys
import json

def main():
    json_input = sys.stdin.read()
    data = json.loads(json_input)
    over_18 = [(person['name'], person['age']) for person in data if person['age'] > 18]
    # Bubble sort by age descending
    n = len(over_18)
    for i in range(n):
        for j in range(0, n - i - 1):
            if over_18[j][1] < over_18[j + 1][1]:
                over_18[j], over_18[j + 1] = over_18[j + 1], over_18[j]
    print(over_18)

if __name__ == "__main__":
    main()
